INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('674ac72d-880e-429d-90e6-570d3c571ec1', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$61. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek$q$, $q$Egyenlő szárú háromszög tulajdonságai és szimmetriatengelye.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "47f1eeb2-79a8-4a65-97dc-cbe90323785c", "text": "Hány szimmetriatengelye van az egyenlő szárú (nem egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "31bd05a7-621c-48c2-9a59-7ae31564826e", "text": "Hány szimmetriatengelye van a szabályos (egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "c05174f9-408f-4f5e-8739-f7f3bbcc7e6f", "text": "Az egyenlő szárú háromszög alapon fekvő szögei egyenlők.", "type": "true-false", "options": [{"id": "8fec1563-b50b-4b37-8d81-f09bd354b715", "text": "Igaz", "isCorrect": true}, {"id": "e17af0d4-15d8-4b3c-a7e6-fe47cffda281", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56772ddd-bded-4b23-8b72-8a6930b094e3", "text": "Ha az egyenlő szárú háromszög szárai 8 cm-esek, és alapja 5 cm, mennyi a kerülete? (8+8+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "21"}, {"id": "bcc4c66a-75b4-40f0-9b4e-5bd73ad69732", "text": "Ha az egyenlő szárú háromszög szárszöge (csúcsszöge) 40°, mekkorák az alapon fekvő szögek? ((180-40)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "168890a5-2b18-43f2-a7e8-bba4e115e9ef", "text": "Az egyenlő szárú háromszög szimmetriatengelye az alap felezőmerőlegese és a szárszög felezője is egyben.", "type": "true-false", "options": [{"id": "505bc3aa-0e62-424e-bb62-2b71cb4577ad", "text": "Igaz", "isCorrect": true}, {"id": "076a4148-6654-4d85-a308-21e7e42d4b96", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2d5ab369-8589-4ea5-90a0-932d75b29071", "text": "Az egyenlő oldalú háromszög minden szöge 60°-os.", "type": "true-false", "options": [{"id": "3daaf5cf-2d90-4a45-926f-63660d735e9e", "text": "Igaz", "isCorrect": true}, {"id": "dc65a7bc-07b5-4167-bf63-131f38ac3120", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('215b664c-b31e-44fa-afaf-703fc3bf70b1', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$62. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek II.$q$, $q$Tengelyesen szimmetrikus négyszögek (téglalap, négyzet, rombusz, deltoid, szimmetrikus trapéz) szimmetriatengelyei.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "8e7b1516-d0fa-48ee-b2e4-dc317011c751", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "69692b4d-613e-4f3b-9e12-e8abcc02f7da", "text": "Hány szimmetriatengelye van a téglalapnak (ami nem négyzet)? (az oldalfelező merőlegesek)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "158d67e0-d5ab-4cc1-ad65-cfdd44b171ae", "text": "Hány szimmetriatengelye van a rombusznak (ami nem négyzet)? (az átlók egyenesei)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "ffa04506-1884-4e12-8e04-61111c32aff1", "text": "Hány szimmetriatengelye van a deltoidnak (ha nem rombusz)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "20b50285-83d2-4a5f-9207-1ad4ef990c61", "text": "A szimmetrikus (egyenlő szárú) trapéznak 1 szimmetriatengelye van.", "type": "true-false", "options": [{"id": "6eb00cbd-0ed3-4390-a4b4-36fae148567b", "text": "Igaz", "isCorrect": true}, {"id": "d076e9be-fd1c-4fcf-a311-e71415774dbc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eb57b4ea-7608-4771-a116-8a29141b0038", "text": "Az általános paralelogrammának (ami nem rombusz és nem téglalap) NINCS tengelyes szimmetriatengelye.", "type": "true-false", "options": [{"id": "ece96fc7-2a33-478f-a247-4e9872bc8737", "text": "Igaz (középpontosan szimmetrikus, de tengelyesen nem)", "isCorrect": true}, {"id": "3e3c59c8-4206-42f9-a047-9258b0649764", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d828c32b-aa7f-46d3-86ac-c85532ed65ea", "text": "Hány szimmetriatengelye van a szabályos ötszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('637420e2-746a-47da-a053-b57b8880e47b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$63. óra: Szerkesztési feladatok$q$, $q$Szakasz- és szögmásolás, szögfelezés, háromszögszerkesztések gyakorlása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "a367f46f-71fb-4fc8-b953-946006e3728d", "text": "Hogyan felezünk meg egy 80°-os szöget szerkesztéssel?", "type": "multiple-choice", "options": [{"id": "d8e43cca-7fc6-4022-9f8b-c5257b73b8f8", "text": "Megszerkesztjük a szög szögfelező egyenesét, így két 40°-os szöget kapunk", "isCorrect": true}, {"id": "c7503fbb-0ac3-40fb-a8cf-00943be188cb", "text": "Levágunk belőle 10 fokot", "isCorrect": false}, {"id": "41eff581-48f6-4496-aebd-1fd21db1f298", "text": "Merőlegest húzunk a szög egyik szárára", "isCorrect": false}, {"id": "369559d6-cd1c-4b16-854a-8a83f7d90593", "text": "Szögmérővel elosztjuk", "isCorrect": false}], "timeLimit": 15}, {"id": "b5b78663-4db6-4029-9032-53727c406bc2", "text": "A szögfelezéshez körzőt és egyenes vonalzót használsz.", "type": "true-false", "options": [{"id": "d36a3cd4-d6b4-41ee-86c1-911ad43ee970", "text": "Igaz", "isCorrect": true}, {"id": "936bb2d6-68e0-4fec-85eb-90cd8b76498e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0ba72945-7be8-47a2-a243-ded8cb7369c8", "text": "Hány fokos szögeket kapunk egy 90°-os derékszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "db15b7a5-ba3e-4109-8650-3e6049344a50", "text": "Hány fokos szögeket kapunk egy 180°-os egyenesszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "29030e24-b61f-40e6-ad04-531cbeaabafe", "text": "Szerkeszthető-e 60°-os szög kizárólag körzővel és vonalzóval (szabályos háromszög szerkesztésével)?", "type": "true-false", "options": [{"id": "fb39316d-6372-4ccf-a973-eb0051f5fd7e", "text": "Igaz", "isCorrect": true}, {"id": "c35ec9e5-605c-4005-baa0-cbc4525d3e02", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "99322b9d-2a18-4fd7-aade-7018a9816b33", "text": "Szerkeszthető-e 30°-os szög a 60°-os szög felezésével?", "type": "true-false", "options": [{"id": "5f60fef0-ddf5-4ed5-a8de-d0391f11d5af", "text": "Igaz", "isCorrect": true}, {"id": "fe2e6dbd-8de8-449c-9e74-63657b8cc536", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "38bf6de1-ce49-4c4d-b590-819dd58526b8", "text": "Szerkeszthető-e 15°-os szög a 30°-os szög felezésével?", "type": "true-false", "options": [{"id": "d4993e62-36dc-456d-a7ef-afdd52a97746", "text": "Igaz", "isCorrect": true}, {"id": "5cd7633b-9290-419a-8752-bd3ffb43604f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4da89a0d-fa56-4351-bce0-90235552dc27', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$64. óra: Dinamikus szerkesztőprogram megismerése$q$, $q$Interaktív geometriai szoftverek (GeoGebra), alakzatok mozgatása, tulajdonságok megfigyelése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "f93d776f-0b25-45dd-842b-7ebe1018addf", "text": "Mire való a GeoGebra dinamikus geometriai program?", "type": "multiple-choice", "options": [{"id": "9fdf30e3-478c-4cbf-8348-10792b5f774e", "text": "Geometriai alakzatok szerkesztésére, mozgatására, mérésére és összefüggések felfedezésére", "isCorrect": true}, {"id": "489495cb-688e-4084-8b04-ca3f68e777d6", "text": "Szövegszerkesztésre", "isCorrect": false}, {"id": "3a2bcd8d-5e32-46f8-92b7-b4edc7255ed6", "text": "Videóvágásra", "isCorrect": false}, {"id": "8a344310-dde8-41e1-b4a2-dfad1dbe2bc8", "text": "Kódolásra C++ nyelven", "isCorrect": false}], "timeLimit": 15}, {"id": "7b9b39c7-c895-4af0-823d-ef436cef1d52", "text": "Dinamikus szerkesztőprogramban az csúcsok mozgatásakor az alakzat tulajdonságai és összefüggései megőrződnek.", "type": "true-false", "options": [{"id": "ca40b2bf-917f-43ea-b972-40df256e8ee0", "text": "Igaz", "isCorrect": true}, {"id": "192c7019-acfc-4221-b6f2-7348904dff77", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9a782b80-29dc-4cdf-aa1c-fc547787d9e0", "text": "A dinamikus programokban a háromszög belső szögeinek összege mozgattatás közben is mindig 180° marad.", "type": "true-false", "options": [{"id": "df0e08ee-d6d4-4f29-9c18-c91132aa6d6a", "text": "Igaz", "isCorrect": true}, {"id": "ba00bfea-9f89-46e9-a23e-bd26700b08ac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "011e4432-3134-4bcc-ab34-8fc141de8f9a", "text": "A szerkesztőprogram segítségével ellenőrizhető a kézi szerkesztések pontossága.", "type": "true-false", "options": [{"id": "8464a80a-6227-41a7-8e9b-e173a54f35e9", "text": "Igaz", "isCorrect": true}, {"id": "f2eb5cf8-dd4c-4a9d-814e-fedbf4c20bdc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "60a742e2-a1ae-4212-a9c4-5642027ae1d3", "text": "Melyik funkció segít a pontok tengelyes tükörképének azonnali előállításában a szoftverben?", "type": "multiple-choice", "options": [{"id": "cf3cf2b0-ab22-4724-8171-4afb97c00509", "text": "Tengelyes tükrözés eszköz", "isCorrect": true}, {"id": "6b33ff25-d216-4919-bcb9-2ef9321c783e", "text": "Színezés", "isCorrect": false}, {"id": "55a3f78e-5f92-4a1b-b162-bbf0ea1c75a8", "text": "Törlés", "isCorrect": false}, {"id": "c8727e0b-5848-4553-9374-1283ce895df2", "text": "Nagyítás", "isCorrect": false}], "timeLimit": 15}, {"id": "03597741-f74d-4e4b-a240-93a864c46982", "text": "A számítógépes geometriai modellezés segíti a mélyebb megértést.", "type": "true-false", "options": [{"id": "c1cc589e-4210-4b3a-9c25-496e1e8d8bf4", "text": "Igaz", "isCorrect": true}, {"id": "613b6b99-f021-49f5-bf91-3a4c1be82d97", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0d0be5df-7c60-4a93-926c-e3e84e886b28", "text": "Hány fok a teljes szög a geometriában?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('842bf0a2-b476-49b5-a2da-c8043508acf2', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$65. óra: Összefoglalás$q$, $q$A Geometria és tengelyes tükrözés fejezet fogalmainak, szerkesztéseinek összefoglalása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "8c20ca5e-d98e-421f-b1c6-faf013014dba", "text": "Hány szimmetriatengelye van a téglalapnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "bf97823e-9d93-44f4-9279-d6ddc96f4437", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "42b7acb5-8e16-46cd-81ce-bedcf4b1c5c1", "text": "A tengelyes tükrözés megváltoztatja a síkidom körüljárási irányát.", "type": "true-false", "options": [{"id": "a7af1cb3-efeb-4bb8-b8aa-048d23a44a39", "text": "Igaz", "isCorrect": true}, {"id": "c9ecaed9-6c13-4dbf-a720-8ca25921032a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "751b7521-41f4-4151-b0ba-ef8b24f2d189", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "8d8bd896-455d-45e3-a5fc-6f51e744ecb4", "text": "A szakaszfelező merőleges minden pontja egyenlő távolságra van a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "7c67aea2-d1a1-4321-945a-0506978dd5f2", "text": "Igaz", "isCorrect": true}, {"id": "0d3ec3ec-46f5-44df-a702-6926fecaeaa3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f26894b8-fe9c-46fb-8d3e-3b66a1d4f25c", "text": "Ha a kör átmérője 12 cm, mekkora a sugara? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "49581637-604c-4a27-8274-476ad9e81866", "text": "A szögfelező egyenes felezi a szöget és egyenlő távolságra van a szög száraitól.", "type": "true-false", "options": [{"id": "f00ce2a0-0798-4a57-84d2-116f47d0b4fd", "text": "Igaz", "isCorrect": true}, {"id": "f0f8b31f-7ae8-494a-8696-96fbe8bee967", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1c05add9-7eee-42a8-a9ca-32ff9e1a3f72', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$66. óra: Témazáró dolgozat$q$, $q$Témazáró számonkérés a Geometria és tengelyes tükrözés fejezetből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "ac4da158-6ac9-405c-a86a-a05f1fe0aae3", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "94edaacb-f12a-4a51-b414-da2b7def4507", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "dea6a9a4-cdee-47ad-96f4-020c27c09e9e", "text": "3. Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "3437b55d-e711-4ea6-91f0-7623532cb4f5", "text": "4. Hány szimmetriatengelye van az egyenlő szárú (nem szabályos) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "1c443552-6924-4d55-a2a7-5526144cc617", "text": "5. Ha a kör sugara 4,5 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "d01cec15-de76-44b4-8ea9-7e3a376c8ea2", "text": "6. A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "f77c4f0d-1b42-47b6-8f5a-6ffff8ceaa07", "text": "Igaz", "isCorrect": true}, {"id": "aa38a5c1-2930-495e-8c22-7421fec20e92", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "49b260e0-147f-489f-81ed-f5f139e65c20", "text": "7. Szerkeszthető-e háromszög 3 cm, 5 cm, 9 cm oldalakkal?", "type": "true-false", "options": [{"id": "8726f5f7-ab8b-446c-8374-e772698f4e9b", "text": "Igaz", "isCorrect": false}, {"id": "03fe7043-0e06-416f-9149-a2590bae1b54", "text": "Hamis (3+5 < 9)", "isCorrect": true}], "timeLimit": 15}, {"id": "86020ee6-6336-4874-9bdd-f5cfebd6014b", "text": "8. Hány fokos szögeket kapunk egy 120°-os szög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "e9300994-00dc-4e1c-894f-4649095a61d0", "text": "9. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "09d2faca-4a19-4282-a7cc-fa7d8c0d98cf", "text": "Igaz", "isCorrect": true}, {"id": "3a4e2e15-2363-4f50-b3e5-33b63b0b7fa4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2caec0f6-95fd-4ba8-b717-f8378a4bc0a4", "text": "10. Hol található a tükörtengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "04296f24-bb1d-4b75-91e1-721a0c5858dc", "text": "Önmagában", "isCorrect": true}, {"id": "a339c877-c287-496f-9e7c-a534526157b5", "text": "Az origóban", "isCorrect": false}, {"id": "573e7c2f-c055-42af-98f3-10c43d7846df", "text": "A tengely végétől 5 cm-re", "isCorrect": false}, {"id": "df45ba28-eb9c-49e8-9bce-a1d286878cf2", "text": "A sík szélén", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a8e21a30-d01c-4e3f-9bae-88be821ed7d4', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$67. óra: Témazáró dolgozat értékelése$q$, $q$A geometriai témazáró megbeszélése, szerkesztések értékelése és hibajavítás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "c05cecb3-ba94-47c9-943a-31176a3838c2", "text": "Mi volt a leggyakoribb hiba a szerkesztési feladatok során?", "type": "multiple-choice", "options": [{"id": "55b37df8-b39a-4189-8594-2e1f3374a658", "text": "A körző pontatlan használata és a háromszög-egyenlőtlenség figyelmen kívül hagyása", "isCorrect": true}, {"id": "e61a52b4-49f8-43ca-a90d-896ff32ad369", "text": "A ceruza színe", "isCorrect": false}, {"id": "5b1891f0-88e2-4b42-b18b-95aca0a1543a", "text": "A füzet vonalazása", "isCorrect": false}, {"id": "63870e99-69f0-407e-8ea0-3f71b6c34ed9", "text": "A számok leírása", "isCorrect": false}], "timeLimit": 15}, {"id": "626881b6-d1e6-4d76-b059-0558ae56b23d", "text": "A szakaszfelező merőleges merőleges a szakaszra és átmegy a felezőpontján.", "type": "true-false", "options": [{"id": "7bac0722-00f1-4c2e-927d-58bf760855e0", "text": "Igaz", "isCorrect": true}, {"id": "53a221c2-1e6f-4923-908e-152caa2b08a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "59e773f9-8ddf-41be-9cf4-d229e13dc002", "text": "Mennyi a kör átmérője, ha a sugara 10 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "93ed295b-ce1d-4cf9-a0ea-509937d74824", "text": "A tengelyes tükrözés során a síkidom területe nem változik.", "type": "true-false", "options": [{"id": "050ea131-4f3a-4c8c-9dec-53ad5348b184", "text": "Igaz", "isCorrect": true}, {"id": "8fa7d050-565c-4516-be86-9bc3166a607f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6280284a-6f34-4f31-9a6b-83c3c1a3c37b", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "39ebbc9d-a81a-4611-9ceb-3ee5bf0ab928", "text": "Végtelen sok", "isCorrect": true}, {"id": "c71d3af4-a71d-4b43-bc99-28716f324d44", "text": "1", "isCorrect": false}, {"id": "e780e2cc-5a1b-4cfd-820a-7a4e92b98504", "text": "2", "isCorrect": false}, {"id": "7273ece6-c5b2-44a4-8227-10c5547f4a5c", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "a6ece943-ec9d-4349-8129-0c76476a2792", "text": "A pontos vázlatkészítés megkönnyíti a bonyolultabb szerkesztések elvégzését.", "type": "true-false", "options": [{"id": "199ddfbf-a560-4b7f-81e3-cd3edc9f07d5", "text": "Igaz", "isCorrect": true}, {"id": "d355de51-0fd4-4fa0-95c8-0387b518c54c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8cac603c-1370-4bfc-b8d4-37f5024859ef", "text": "Mennyi a háromszög harmadik szöge, ha az első kettő 50° és 70°?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8bb2f179-a95e-4c80-9ca9-b75eb1df05e9', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$68. óra: Az arány fogalma$q$, $q$Az arány fogalma, felírása kettősponttal és törttel, értelmezése hétköznapi példákban.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "550c79ce-398d-4b80-87d9-93259531cc3f", "text": "Mit fejez ki két mennyiség aránya?", "type": "multiple-choice", "options": [{"id": "1c12e0b0-fa4f-4211-a0b9-eb6eb2b87c14", "text": "Megmutatja, hányszorosa az egyik mennyiség a másiknak (hányadosukat)", "isCorrect": true}, {"id": "f230a1b8-29c6-45ca-836a-57406304fe25", "text": "Megmutatja a két mennyiség összegét", "isCorrect": false}, {"id": "4d2dfece-0a4c-47f6-89c0-8ffb1f774016", "text": "Megmutatja a két mennyiség szorzatát", "isCorrect": false}, {"id": "53b960b6-fb11-42c9-ac6d-a625c67db08b", "text": "Nem fejez ki semmit", "isCorrect": false}], "timeLimit": 15}, {"id": "932a7500-4851-4134-ba2d-22b33389ecde", "text": "Hogyan jelöljük az arányt matematikailag?", "type": "multiple-choice", "options": [{"id": "64316a70-de87-4a3e-8de8-bc82fa1f057e", "text": "Kettősponttal (pl. 2 : 3) vagy törttel (2/3)", "isCorrect": true}, {"id": "ac59009a-c884-482f-a63a-84fb58b8c151", "text": "Plusz jellel", "isCorrect": false}, {"id": "7937f77f-a118-49ac-99f5-32bbb7fc0b60", "text": "Csillaggal", "isCorrect": false}, {"id": "89293891-198d-4633-8f17-16851a8f3408", "text": "Egyenlőségjellel", "isCorrect": false}], "timeLimit": 15}, {"id": "279e84cb-f2d4-4a2a-a003-d1c82e586ba6", "text": "Ha egy osztályban 10 fiú és 15 lány van, mi a fiúk és lányok számának aránya legegyszerűbb alakban?", "type": "multiple-choice", "options": [{"id": "941a48b7-3e1c-4cea-8586-3ca79580f4e6", "text": "2 : 3 (10/15 egyszerűsítve 5-tel)", "isCorrect": true}, {"id": "4c2c16b0-c743-45cf-a73e-633891226b4d", "text": "1 : 2", "isCorrect": false}, {"id": "8b3a78a3-7528-4fc5-a4b2-fa1fca2bcc3f", "text": "3 : 2", "isCorrect": false}, {"id": "0a97e820-bf89-436d-b2fe-5370b71e8d21", "text": "10 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "74f5e1be-898a-4479-a4df-895538bf10a5", "text": "Az arány a törtekhez hasonlóan egyszerűsíthető és bővíthető.", "type": "true-false", "options": [{"id": "0c7fc43e-710a-4618-987f-9ddaedf15fda", "text": "Igaz", "isCorrect": true}, {"id": "e6695756-b57d-4e72-9bdf-23b64b974d4a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3fca76d5-0eb6-4b34-a557-942ffc4bebab", "text": "Mennyi a 4 : 8 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "ad4faff2-2e9a-4e0e-8573-e4cabb392067", "text": "1 : 2", "isCorrect": true}, {"id": "e0586cd4-be4d-4db7-b6a3-c5adbdaa4a5d", "text": "2 : 4", "isCorrect": false}, {"id": "74ddfb8d-a168-4239-b369-1694b33f38ae", "text": "1 : 4", "isCorrect": false}, {"id": "653025b5-f0ab-42e9-9c29-9be256547db0", "text": "4 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "38a55649-d935-4ffa-9319-df231db46d6f", "text": "Ha az arány 3 : 1, az első mennyiség 3-szor akkora, mint a második.", "type": "true-false", "options": [{"id": "2c8078c6-0e60-457a-aa3b-028f09cada7c", "text": "Igaz", "isCorrect": true}, {"id": "2475e5c6-6003-4f65-90f1-8566d2ae889a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c2bb4c3-2df3-4d86-953b-789a43781c02", "text": "Melyik arány egyenlő az 1 : 2 aránnyal?", "type": "multiple-choice", "options": [{"id": "ea0d459e-d8b4-42a6-bdb1-a58bfc267132", "text": "5 : 10", "isCorrect": true}, {"id": "de6a7b3c-2d09-401f-84dd-647bce326cd9", "text": "2 : 1", "isCorrect": false}, {"id": "276a63b0-3de5-4395-89e6-e77867c30b93", "text": "3 : 5", "isCorrect": false}, {"id": "bf27b25e-e6fe-4ec8-a7ee-fa179768dae1", "text": "4 : 6", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bbece7a0-3713-4200-bca8-1e5a17dd2a8f', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$69. óra: Arányos osztás$q$, $q$Adott mennyiség felosztása megadott arányban (pl. 2 : 3 arányban).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "86340c6c-2ce6-4c31-a751-603e1f8f38a7", "text": "Ha 500 Ft-ot elosztunk 2 : 3 arányban, hány egyenlő részre osztjuk először a teljes összeget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "b7fb248e-401d-4f25-a165-c0f48eac345e", "text": "Hány Ft a kisebbik rész 500 Ft 2 : 3 arányú felosztásakor? (1 rész = 100 Ft, 2 rész = 200 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "5ec0cca3-0be5-4e5a-b7c5-ab7ae78e8b7d", "text": "Hány Ft a nagyobbik rész 500 Ft 2 : 3 arányú felosztásakor? (3 rész = 300 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "19d71368-cdf9-4fc8-b3f2-e466cf1c1bc9", "text": "Az arányos osztásnál az arányszámok összege megadja az összes egység (rész) számát.", "type": "true-false", "options": [{"id": "fe6b80c9-6f8d-42f5-a585-d24e948154ca", "text": "Igaz", "isCorrect": true}, {"id": "0ed77107-de9a-46dd-ba26-0147af9f2e03", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9f87fd27-3703-4d40-8b2d-0f35d29ec897", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a nagyobbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "99aeadb5-30bf-425e-97f2-6b130e57574a", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a kisebbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e86da56d-d429-4539-a3ac-cdeb77c89634", "text": "Az arányos osztási feladatok ellenőrizhetők a kapott részek összegzésével.", "type": "true-false", "options": [{"id": "965758c8-7762-4e27-b708-475a74f17a12", "text": "Igaz", "isCorrect": true}, {"id": "3bf62473-6f15-475d-8a07-0972afd52da1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a90d6d7e-25da-4db8-8822-30bad89eba2a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$70. óra: Feladatok megoldása$q$, $q$Hétköznapi recept, ötvözet, keverék és arányos osztási feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "1af50a74-8448-4b63-8b21-2e5acae0d371", "text": "Egy habarcs készítéséhez homok és mész kell 4 : 1 arányban. Hány kg homok kell 50 kg habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "4b2dd5b8-765d-4d4b-ae30-32d71858a241", "text": "Egy szörp elkészítéséhez szörp és víz kell 1 : 4 arányban. Hány dl szörp kell 10 dl (1 liter) italhoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "fb9b60b3-0d16-4675-a4d0-95e62c25d980", "text": "Ha két testvér 3 : 5 arányban osztozik 800 Ft-on, a nagyobbik rész 500 Ft.", "type": "true-false", "options": [{"id": "a17a82a2-ff1f-477b-9360-ae091a9e68b4", "text": "Igaz (800 / 8 = 100, 5 * 100 = 500)", "isCorrect": true}, {"id": "c7b517d6-9064-4251-b6c2-46fd674b6a70", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "263119e4-954f-4eb1-9d1b-63db74f32672", "text": "Egy téglalap két szomszédos oldalának aránya 2 : 3. Ha a rövidebb oldal 6 cm, hány cm a hosszabb oldal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "0b2fce6f-4376-4f3a-9580-a75ba59b6387", "text": "Melyik állítás igaz az arányos osztásra?", "type": "multiple-choice", "options": [{"id": "da358c3e-5dbe-40aa-907d-7002acebc7b7", "text": "A kapott részek aránya megegyezik a megadott aránnyal", "isCorrect": true}, {"id": "95974fdb-ce94-4f1c-baf9-02f6b5f277fb", "text": "Minden rész egyenlő nagyságú", "isCorrect": false}, {"id": "2291bb71-421a-4c98-9440-d64e4d9ff900", "text": "A részek összege kisebb az eredeti mennyiségnél", "isCorrect": false}, {"id": "eb3cb6b3-a964-4980-8790-19e158a11068", "text": "Nem lehet kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "d1cd0675-d48b-48c4-8cac-e1320f160fc8", "text": "Hány g mész kell 50 kg (4:1 arányú) habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d800b1dc-f28d-4c42-b536-72816120808c", "text": "A receptekben megadott hozzávalók aránya lehetővé teszi tetszőleges adag elkészítését.", "type": "true-false", "options": [{"id": "b000ab00-777a-4ef5-82bd-9ca839fb558c", "text": "Igaz", "isCorrect": true}, {"id": "35169b43-f443-4d0d-8a58-279a3ff93ef9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;